// Generated by vibelang from e2e/spend.ts; the migrate flow writes it again with each batch.
// The spend guard (docs/infrastructure.md#against-a-deployment): a run against a deployment spends its real model
// budget, which its people share. Before each test the guard adds up the tokens the run's answers have used, as the
// server recorded them on each answer (`input_tokens` and `output_tokens`, worker/Chat.ts), and once the total reaches
// the run's budget every later test fails with `SpendBudgetSpent` instead of asking. It counts the answers in the
// conversation the run asks in; a model call that writes no answer, such as a judge's, isn't counted.
/** The run's budget in tokens when `E2E_TOKEN_BUDGET` is unset: about 40 asks at today's 14,000 tokens each. */
export const DEFAULT_TOKEN_BUDGET = 600_000;
/** How long a worker trusts the total it read last before reading the conversation again. */
export const REREAD_MS = 60_000;
export const tokenBudget = (env) => {
    const named = env.E2E_TOKEN_BUDGET ?? "";
    if (named === "")
        return DEFAULT_TOKEN_BUDGET;
    const budget = Number(named);
    if (!Number.isSafeInteger(budget) || budget <= 0)
        throw new Error(`E2E_TOKEN_BUDGET is "${named}": it must be a whole number of tokens above 0`);
    return budget;
};
/** Postgres' text form of a timestamp (`2026-10-21 17:03:04.123456+00`) as ms since the epoch; NaN when it isn't one. */
export const parseTimestamp = (text) => {
    const match = /^(\d{4}-\d\d-\d\d)[ T](\d\d:\d\d:\d\d)(\.\d+)?(Z|[+-]\d\d(?::?\d\d)?)$/.exec(text);
    if (match === null)
        return Number.NaN;
    const [, date, time, fraction = "", zone] = match;
    const offset = zone === "Z" ? "Z" : /^[+-]\d\d$/.test(zone) ? `${zone}:00` : zone.replace(/^([+-]\d\d)(\d\d)$/, "$1:$2");
    return Date.parse(`${date}T${time}${fraction.slice(0, 4)}${offset}`);
};
/** The tokens the answers written since `since` (ms since the epoch) used. */
export const spentSince = (rows, since) => {
    let total = 0;
    for (const row of rows) {
        if (row.role !== "assistant" || row.created_at === undefined || !(parseTimestamp(row.created_at) >= since))
            continue;
        total += Number(row.input_tokens ?? 0) + Number(row.output_tokens ?? 0);
    }
    return total;
};
/** How many reads in a row may fail before the guard stops tests: past it, the run's spend is unknown. */
export const MAX_UNREAD = 3;
/** The guard couldn't read the run's spend `reads` times in a row: no test that may spend starts. */
export class SpendUnknown extends Error {
    reads;
    name = "SpendUnknown";
    constructor(reads) {
        super(`The run's spend couldn't be read ${reads} times in a row (the messages shape): this test doesn't start.`);
        this.reads = reads;
    }
}
/** The run's answers used its whole budget: the rest of the run asks nothing. */
export class SpendBudgetSpent extends Error {
    spent;
    budget;
    name = "SpendBudgetSpent";
    constructor(spent, budget) {
        super(`The run's answers used ${spent} tokens, its budget is ${budget} (E2E_TOKEN_BUDGET): this test doesn't start.`);
        this.spent = spent;
        this.budget = budget;
    }
}
/** When the run began: playwright.config.ts sets it once, and every worker inherits it. */
export const runStartedAt = (env) => {
    const at = Number(env.E2E_RUN_STARTED_AT);
    if (!Number.isFinite(at) || at <= 0)
        throw new Error("E2E_RUN_STARTED_AT is unset: playwright.config.ts sets it for a deployment run");
    return at;
};
/**
 * The guard a worker runs before each test: it fails the test once the run's answers spent the budget. It reads the
 * conversation at most once a `REREAD_MS`, so a run of many short tests reads it a few times a minute. A read that
 * fails, such as Electric's 503 while it starts, is reported through `unread` and tried again before the next test;
 * `MAX_UNREAD` failures in a row stop tests with `SpendUnknown`, since the spend can no longer be bounded.
 */
export const spendGuard = (options) => {
    const now = options.now ?? Date.now;
    let last;
    let unread = 0;
    return async () => {
        if (!options.applies())
            return;
        const budget = options.budget();
        if (last === undefined || now() - last.at >= REREAD_MS) {
            const spent = await options.rows().then((rows) => spentSince(rows, options.since()), (error) => {
                options.unread(error);
                return undefined;
            });
            unread = spent === undefined ? unread + 1 : 0;
            if (unread >= MAX_UNREAD)
                throw new SpendUnknown(unread);
            if (spent !== undefined)
                last = { at: now(), spent };
        }
        if (last !== undefined && last.spent >= budget)
            throw new SpendBudgetSpent(last.spent, budget);
    };
};
